'use strict';
let bgmAudio=null;
function stopBgmPreview(){if(bgmAudio){bgmAudio.pause();bgmAudio.removeAttribute('src');bgmAudio.load();bgmAudio=null;}}
const renderDialogueWithoutMusic=renderDialogue;
renderDialogue=function(){stopBgmPreview();renderDialogueWithoutMusic();const commands=model.musicCommands(stage,{part:currentFlow?.part||'before',root:currentFlow?.root}),card=document.createElement('div');card.id='musicCard';card.className='card';const usage={3:'原剧情：忍者学校、中央塔',4:'原剧情：波之国及多处任务',5:'原剧情中的音乐',7:'原剧情中的音乐',8:'原剧情中的音乐',13:'原剧情中的音乐'};card.innerHTML=`<h3>剧情音乐与试听</h3><p class="hint">原版 18 首音乐的约 15 秒试听片段。先听再选择；试听音量只影响编辑器。曲目名称按原版编号保留。</p><div class="toolbar"><label>试听曲目<select id="bgmTrack">${opts(E.musicCatalog.map(t=>[t.id,`${t.label}${usage[t.id]?' · '+usage[t.id]:''}`]),commands[0]?.id||4)}</select></label><button id="bgmPlay" type="button">播放试听</button><button id="bgmStop" type="button">停止</button></div><audio id="bgmAudio" controls preload="none" style="width:100%"></audio><p id="bgmStatus" role="status" class="hint">点击播放；播放条可暂停、拖动进度和调节音量。</p>${commands.length?`<div class="toolbar"><label>应用到这段剧情的<select id="bgmCommand">${commands.map((c,i)=>`<option value="${c.offset}">第 ${i+1} 处音乐 · 当前曲目 ${c.id}</option>`).join('')}</select></label><button id="bgmApply" type="button">使用此曲目</button></div><p class="hint">只修改当前选择的音乐指令；战前与战后分别设置。保存工程或导出新 ROM 后生效。</p>`:'<p class="hint">这段剧情没有可单独替换的原版音乐指令，可以试听全部曲目。新增战斗请先导出、重新打开 ROM，再设置其战前和战后音乐。</p>'}`;const anchor=$('#storyBackground')||panel.firstElementChild;anchor.after(card);const audio=$('#bgmAudio');bgmAudio=audio;audio.volume=.6;const selected=()=>E.musicCatalog.find(t=>t.id===+$('#bgmTrack').value);const load=()=>{audio.pause();audio.src=selected().file;audio.load();$('#bgmStatus').textContent=`已选择${selected().label}，点击播放试听。`;};$('#bgmTrack').onchange=load;$('#bgmPlay').onclick=async()=>{try{if(!audio.getAttribute('src'))load();await audio.play();$('#bgmStatus').textContent=`正在试听${selected().label}（原版录音片段）`;}catch(e){$('#bgmStatus').textContent='试听未能播放，请确认 music 文件夹与编辑器一起解压，并再次点击播放。';}};$('#bgmStop').onclick=()=>{audio.pause();audio.currentTime=0;$('#bgmStatus').textContent='已停止试听。';};if(commands.length)$('#bgmApply').onclick=()=>run(()=>transaction('修改剧情音乐',()=>model.setMusic(stage,+$('#bgmCommand').value,+$('#bgmTrack').value)));};
document.querySelector('#tabs').addEventListener('click',e=>{if(e.target.dataset.tab&&e.target.dataset.tab!=='dialogue')stopBgmPreview();});window.addEventListener('romloaded',stopBgmPreview);window.addEventListener('beforeunload',stopBgmPreview);
